functions.getGridWidth:
function getGridWidth() {
		try {
			var w = window.parent.$("#screensWrapper").width();
			if(w>100)
				return window.parent.$("#screensWrapper").width()-10;
			else
				return $(window).width()-10;
		} catch (e) {
			console.log(e.message);
			return $(window).width()-10;
		}
	}

functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.openRequestResponseBody:
function openRequestResponseBody(event, id){
			if(id != undefined && id != null && id != "") {

				var retVal = $.ajax({
					url : "fetchTrackingRequestResponseById",

					type : "POST",
					data : {
						transId : id
					},
					dataType : "json",
					async : false
				}).responseText;

				retVal = jQuery.parseJSON(retVal);
				if(retVal != null && retVal != undefined && retVal.deviceTrackingLogDTO != null 
						&& (retVal.deviceTrackingLogDTO.requestJson != null || retVal.deviceTrackingLogDTO.responseJson != null)){
					if(retVal.deviceTrackingLogDTO.requestJson != undefined && retVal.deviceTrackingLogDTO.requestJson != "")
						editor.setValue(JSON.stringify(JSON.parse(retVal.deviceTrackingLogDTO.requestJson), null, '\t'), -1);
					else
						editor.setValue("");

					if(retVal.deviceTrackingLogDTO.responseJson != undefined && retVal.deviceTrackingLogDTO.responseJson != "")
						editor1.setValue(JSON.stringify(JSON.parse(retVal.deviceTrackingLogDTO.responseJson), null, '\t'), -1);
					else
						editor1.setValue("");
					var rowData = jQuery("#trackingLogTable").getRowData(id);
					let str = "";
					if(rowData != undefined && rowData != null && rowData != ""){

						str = "common.invoiceno";
						str += " : " + rowData.documentNo + " [ Exec Time : " + rowData.execTime + "s ]";
					}
					$("#headLabel").html(str);
					$("#requestResponseDialog").modal("show");
				}
				else{
					window.parent.showAlert('Something Went Wrong');
					return false;
				}
			}
		}

functions.openOrderLink:
function openOrderLink(orderNo, orderType,refrenceNo, event){
			if (window.parent){
				if(orderType == "STO")
					window.parent.openScreen("STO Order Create/Edit","stockOrderMaintDisplayBS?stkTransferCode=" + orderNo, "fa fa-fw fa-list-ol");

				else if(orderType == "RETURN"){
					if(refrenceNo != "")
					    window.parent.openScreen("Return Create/Edit-"+orderNo,"custReturnFetchDataBS?custRetCode="+ orderNo, "fa fa-fw fa-list-ol"); 
					else
						window.parent.openScreen("Return W/o Order  - "+orderNo,"custRetWithOutDisplay?custRetCode="+ orderNo, "fa fa-fw fa-list-ol");
				}
				else if(orderType == "RTV")
					window.parent.openScreen("Vendor Return Create/Edit","vendorReturnsFetchDataBS?rtvNo="+ orderNo, "fa fa-fw fa-list-ol");
				else
					window.parent.openScreen("Order Create/Edit - "+orderNo, "orderMaintenanceBS?orderCode="+orderNo, "fa fa-fw fa-simplybuilt");

			  return false;
			}
		 }

