			$("#gbox_"+gridObj[0].id+" .ui-jqgrid-bdiv").css("height",gridHeight+"px").css('overflow-x',($(window).width()<992 ?'auto':'hidden'));
			oldWidth=gridWidth;
		}

functions.reloadSearchGrid:
function reloadSearchGrid(event) {
			reqJsonMap = {};
			respJsonMaps = {};

			if($("#gs_documentNo").val() == "" && $("#gs_referenceNo").val() == "" && $("#gs_referenceNo2").val() == ""){

				if($("#fromUpdDate").val() == "" || $("#toUpdDate").val() == ""){
					tryFocusBS($("#gs_updDate"));
					$("#gs_updDate").attr("readonly", false);
					window.parent.showAlert('Transaction date is mandatory');
					return false;
				}
				var retVal = $.ajax({
					url : "validateDateRange",

					type : "POST",
					data : {
				  		fromDateValue : $("#fromUpdDate").val(),
				    	toDateValue : $("#toUpdDate").val(),
						fieldName : "Txn "
					},
					dataType : "json",
					async : false
				}).responseText;
				retVal = jQuery.parseJSON(retVal);
				if(retVal != null){
					if(retVal.jsonMessage == null){

					} else {
						window.parent.showAlert(retVal.jsonMessage);
						event.preventDefault();
						return false;
					}
				}
			}
			var retVal = $("#trackingLogTable").jqGrid('setGridParam', {
				datatype : 'json',
				page : 1,
				postData : {
					documentNo		:$("#gs_documentNo").val(),
					referenceNo		:$("#gs_referenceNo").val(),
					status			:$("#gs_status").val(),
					errorDesc		:$("#gs_errorDesc").val(),
					fromUpdDate		:$("#fromUpdDate").val(),
					toUpdDate		:$("#toUpdDate").val(),
					clientId		:$("#gs_clientId").val(),
					key1			:$("#gs_key1").val(),
					key2			:$("#gs_key2").val(),
					key3			:$("#gs_key3").val(),
					referenceNo2	:$("#gs_referenceNo2").val(),
					referenceType	:$("#gs_referenceType").val(),
					integrationType :$("#gs_integrationType").val(),
					deviceId		:$("#gs_deviceId").val(),
					REQ_SEARCH_FLAG : true
				},
				url : "jsonDeviceTrackerLogSearch",
				search : true				
			}).trigger('reloadGrid');
		}
